import { KerfTopology } from '../types';

// Physics engine tunable parameters & constants
const MIN_CUT_DISTANCE = 0.06;
const MAX_KERF_INITIATION_DISTANCE = 3.5;

export interface MassNode {
  x: number;
  y: number;
  z: number;
  oldX: number;
  oldY: number;
  oldZ: number;
  accX: number;
  accY: number;
  accZ: number;
  invMass: number;
  strain: number;
  segmentIdx: number;
  radius: number;
}

export interface Spring {
  idxA: number;
  idxB: number;
  restLength: number;
  broken: boolean;
  isKerf?: boolean;
  stiffness?: number;
  breakThreshold?: number;
}

export interface RingTopology {
  pithIdx: number;
  shellIndices: number[];
  originalV: number;
}

export interface LogDefinition {
  radius: number;
  length: number;
  radialSegments: number;
  lengthSegments: number;
  position: [number, number, number];
  rotation: [number, number, number];
}

export class LogModel {
  public nodes: MassNode[] = [];
  public springs: Spring[] = [];
  public segments: RingTopology[][] = [];
  public activeKerfs: KerfTopology[] = [];

  constructor(logs: LogDefinition[]) {
    for (const log of logs) {
      this.generateTopology(log);
    }
  }

  private generateTopology(log: LogDefinition) {
    const { length, radius, radialSegments, lengthSegments, position, rotation } = log;
    
    const nodesPerRing = radialSegments;
    const ringCount = lengthSegments + 1;
    
    const currentSegmentIdx = this.segments.length;
    
    // Create Pith (center axis) nodes
    const pithStartIdx = this.nodes.length;
    for (let i = 0; i < ringCount; i++) {
      const v = i / lengthSegments;
      const lx = v * length; // Start at 0, go to length
      
      this.addNode(lx, 0, 0, position, rotation, currentSegmentIdx, radius);
    }

    const shellStartIdx = this.nodes.length;
    
    const initialSegment: RingTopology[] = [];
    
    for (let i = 0; i < ringCount; i++) {
      const v = i / lengthSegments;
      const lx = v * length;

      const ring: RingTopology = { pithIdx: pithStartIdx + i, shellIndices: [], originalV: v };

      for (let j = 0; j < nodesPerRing; j++) {
        // Cylinder along X-axis: Y and Z form the radial circle
        const u = j / nodesPerRing;
        const theta = u * Math.PI * 2;
        const ly = Math.sin(theta) * radius;
        const lz = Math.cos(theta) * radius;

        ring.shellIndices.push(this.nodes.length);
        this.addNode(lx, ly, lz, position, rotation, currentSegmentIdx, 0);
      }
      
      initialSegment.push(ring);
    }
    
    this.segments.push(initialSegment);

    // Generate Springs
    
    // 1. Pith axis springs
    for (let i = 0; i < ringCount - 1; i++) {
      this.addSpring(pithStartIdx + i, pithStartIdx + i + 1);
    }

    // 2. Shell Structural Springs
    for (let i = 0; i < ringCount; i++) {
      for (let j = 0; j < nodesPerRing; j++) {
        const currentIdx = shellStartIdx + (i * nodesPerRing) + j;
        const nextIdxInRing = shellStartIdx + (i * nodesPerRing) + ((j + 1) % nodesPerRing);
        
        // Ring hoop spring
        this.addSpring(currentIdx, nextIdxInRing);
        
        // Radial spring to pith
        this.addSpring(currentIdx, pithStartIdx + i);

        // Diametric cross bracing (across the face)
        if (j < Math.floor(nodesPerRing / 2)) {
          const oppositeIdx = shellStartIdx + (i * nodesPerRing) + ((j + Math.floor(nodesPerRing / 2)) % nodesPerRing);
          this.addSpring(currentIdx, oppositeIdx);
        }

        // Chordal bracing to prevent star folding
        const chordalIdx = shellStartIdx + (i * nodesPerRing) + ((j + 2) % nodesPerRing);
        this.addSpring(currentIdx, chordalIdx);

        // Longitudinal spring (to next ring)
        if (i < ringCount - 1) {
          const nextRingIdx = shellStartIdx + ((i + 1) * nodesPerRing) + j;
          this.addSpring(currentIdx, nextRingIdx);
          
          // Diagonal shear springs (X-brace for structural integrity)
          const nextRingNextIdx = shellStartIdx + ((i + 1) * nodesPerRing) + ((j + 1) % nodesPerRing);
          this.addSpring(currentIdx, nextRingNextIdx);
          
          const nextRingPrevIdx = shellStartIdx + ((i + 1) * nodesPerRing) + ((j - 1 + nodesPerRing) % nodesPerRing);
          this.addSpring(currentIdx, nextRingPrevIdx);
        }
      }
    }
  }

  private addNode(lx: number, ly: number, lz: number, position: [number, number, number], rotation: [number, number, number], segmentIdx: number, radius: number) {
    // Apply initial rotation and translation
    const [rx, ry, rz] = rotation;
    
    // Rotate X
    let x1 = lx;
    let y1 = ly * Math.cos(rx) - lz * Math.sin(rx);
    let z1 = ly * Math.sin(rx) + lz * Math.cos(rx);
    
    // Rotate Y
    let x2 = x1 * Math.cos(ry) + z1 * Math.sin(ry);
    let y2 = y1;
    let z2 = -x1 * Math.sin(ry) + z1 * Math.cos(ry);
    
    // Rotate Z
    let x = x2 * Math.cos(rz) - y2 * Math.sin(rz);
    let y = x2 * Math.sin(rz) + y2 * Math.cos(rz);
    let z = z2;

    // Translate
    x += position[0];
    y += position[1];
    z += position[2];

    this.nodes.push({
      x, y, z,
      oldX: x, oldY: y, oldZ: z,
      accX: 0, accY: 0, accZ: 0,
      invMass: 1.0, // Make it > 0 so it responds to gravity
      strain: 0,
      segmentIdx,
      radius
    });
  }

  private addSpring(
    idxA: number,
    idxB: number,
    isKerf: boolean = false,
    customRestLength?: number,
    customStiffness?: number,
    customBreakThreshold?: number
  ) {
    let restLength = customRestLength;
    if (restLength === undefined) {
      const nA = this.nodes[idxA];
      const nB = this.nodes[idxB];
      const dx = nA.x - nB.x;
      const dy = nA.y - nB.y;
      const dz = nA.z - nB.z;
      restLength = Math.sqrt(dx*dx + dy*dy + dz*dz);
    }
    this.springs.push({
      idxA,
      idxB,
      restLength,
      broken: false,
      isKerf,
      stiffness: customStiffness,
      breakThreshold: customBreakThreshold
    });
  }

  public getPositionsBuffer(buffer: Float32Array): void {
    for (let i = 0; i < this.nodes.length; i++) {
      buffer[i * 3 + 0] = this.nodes[i].x;
      buffer[i * 3 + 1] = this.nodes[i].y;
      buffer[i * 3 + 2] = this.nodes[i].z;
    }
  }

  public getStrainsBuffer(buffer: Float32Array): void {
    for (let i = 0; i < this.nodes.length; i++) {
      buffer[i] = this.nodes[i].strain;
    }
  }

  public initiateKerf(planePoint: [number, number, number], planeNormal: [number, number, number]) {
    let intersectingRingIdx = -1;
    let activeSegObj: RingTopology[] | null = null;
    let segIdx = -1;
    let ringInSegIdx = -1;
    let t = 0;
    let minDistanceToSaw = Infinity;
    
    // Find closest intersection across all segments (filtering out distant cuts)
    for (let s = 0; s < this.segments.length; s++) {
      const segment = this.segments[s];
      for (let r = 0; r < segment.length - 1; r++) {
        const n1 = this.nodes[segment[r].pithIdx];
        const n2 = this.nodes[segment[r + 1].pithIdx];
        
        const d1 = (n1.x - planePoint[0])*planeNormal[0] + (n1.y - planePoint[1])*planeNormal[1] + (n1.z - planePoint[2])*planeNormal[2];
        const d2 = (n2.x - planePoint[0])*planeNormal[0] + (n2.y - planePoint[1])*planeNormal[1] + (n2.z - planePoint[2])*planeNormal[2];
        
        // Sign change = intersection with plane
        if ((d1 > 0 && d2 <= 0) || (d1 <= 0 && d2 > 0)) {
          const denom = Math.abs(d1) + Math.abs(d2);
          const candT = denom < 1e-6 ? 0.5 : Math.abs(d1) / denom;

          // 3D position of pith intersection point
          const interpX = n1.x + (n2.x - n1.x) * candT;
          const interpY = n1.y + (n2.y - n1.y) * candT;
          const interpZ = n1.z + (n2.z - n1.z) * candT;

          // Distance from chainsaw cut origin to pith intersection point
          const dx = interpX - planePoint[0];
          const dy = interpY - planePoint[1];
          const dz = interpZ - planePoint[2];
          const distToSaw = Math.sqrt(dx * dx + dy * dy + dz * dz);

          // Choose closest segment within valid reach
          if (distToSaw <= MAX_KERF_INITIATION_DISTANCE && distToSaw < minDistanceToSaw) {
            minDistanceToSaw = distToSaw;
            intersectingRingIdx = segment[r].pithIdx;
            t = candT;
            segIdx = s;
            ringInSegIdx = r;
            activeSegObj = segment;
          }
        }
      }
    }
    
    if (intersectingRingIdx === -1 || !activeSegObj) {
      console.warn(`[LogModel] initiateKerf failed: No valid pith segment intersection within ${MAX_KERF_INITIATION_DISTANCE}m of chainsaw position.`);
      return;
    }

    // Prevent duplicate or too-close cuts within MIN_CUT_DISTANCE meters of any segment boundary
    const dist = (idxA: number, idxB: number) => {
      const nA = this.nodes[idxA];
      const nB = this.nodes[idxB];
      const dx = nA.x - nB.x;
      const dy = nA.y - nB.y;
      const dz = nA.z - nB.z;
      return Math.sqrt(dx * dx + dy * dy + dz * dz);
    };

    const pAIdx = activeSegObj[ringInSegIdx].pithIdx;
    const pBIdx = activeSegObj[ringInSegIdx + 1].pithIdx;
    const currentSpanLength = dist(pAIdx, pBIdx);

    let distToStart = t * currentSpanLength;
    for (let i = 0; i < ringInSegIdx; i++) {
      distToStart += dist(activeSegObj[i].pithIdx, activeSegObj[i + 1].pithIdx);
    }

    let distToEnd = (1 - t) * currentSpanLength;
    for (let i = ringInSegIdx + 1; i < activeSegObj.length - 1; i++) {
      distToEnd += dist(activeSegObj[i].pithIdx, activeSegObj[i + 1].pithIdx);
    }

    if (distToStart < MIN_CUT_DISTANCE || distToEnd < MIN_CUT_DISTANCE) {
      console.log(`[LogModel] Ignoring duplicate or too-close cut! Distance to segment boundary: start=${distToStart.toFixed(3)}m, end=${distToEnd.toFixed(3)}m`);
      return;
    }
    
    console.log(`[LogModel] Kerf intersects between rings ${intersectingRingIdx} and ${activeSegObj[ringInSegIdx+1].pithIdx} at t=${t.toFixed(2)}`);
    
    const kerfWidth = 0.04;
    const nodesPerRing = activeSegObj[0].shellIndices.length;


    const ringA_pithIdx = intersectingRingIdx;
    const ringB_pithIdx = activeSegObj[ringInSegIdx + 1].pithIdx;
    const ringA_shell = activeSegObj[ringInSegIdx].shellIndices;
    const ringB_shell = activeSegObj[ringInSegIdx + 1].shellIndices;
    
    // C1 Indices
    const c1_pithIdx = this.nodes.length;
    const c1_shellStart = c1_pithIdx + 1;
    
    // Add C1 Pith & Shell
    const pA = this.nodes[ringA_pithIdx];
    const pB = this.nodes[ringB_pithIdx];
    const pushInterpNode = (nA: MassNode, nB: MassNode, sign: number, segmentIdx: number, interpT: number) => {
      const x = nA.x + (nB.x - nA.x) * interpT + planeNormal[0] * (kerfWidth/2) * sign;
      const y = nA.y + (nB.y - nA.y) * interpT + planeNormal[1] * (kerfWidth/2) * sign;
      const z = nA.z + (nB.z - nA.z) * interpT + planeNormal[2] * (kerfWidth/2) * sign;
      this.nodes.push({ x, y, z, oldX: x, oldY: y, oldZ: z, accX: 0, accY: 0, accZ: 0, invMass: 1.0, strain: 0, segmentIdx, radius: nA.radius });
    };
    
    pushInterpNode(pA, pB, -1, segIdx, t);
    for (let j = 0; j < nodesPerRing; j++) {
      const nA = this.nodes[ringA_shell[j]];
      const nB = this.nodes[ringB_shell[j]];
      const d1 = (nA.x - planePoint[0])*planeNormal[0] + (nA.y - planePoint[1])*planeNormal[1] + (nA.z - planePoint[2])*planeNormal[2];
      const d2 = (nB.x - planePoint[0])*planeNormal[0] + (nB.y - planePoint[1])*planeNormal[1] + (nB.z - planePoint[2])*planeNormal[2];
      const denom = d1 - d2;
      const tj = Math.abs(denom) < 1e-6 ? 0.5 : d1 / denom;
      const tjClamped = Math.max(0, Math.min(1, tj));
      pushInterpNode(nA, nB, -1, segIdx, tjClamped);
    }

    // DEBUG: Log C1 endcap pith position vs ring A/B piths
    const c1Pith = this.nodes[c1_pithIdx];
    console.log(`[KERF DEBUG] t=${t.toFixed(4)}, kerfWidth=${kerfWidth}`);
    console.log(`[KERF DEBUG] planeNormal=(${planeNormal[0].toFixed(3)}, ${planeNormal[1].toFixed(3)}, ${planeNormal[2].toFixed(3)})`);
    console.log(`[KERF DEBUG] RingA pith[${ringA_pithIdx}]: (${pA.x.toFixed(3)}, ${pA.y.toFixed(3)}, ${pA.z.toFixed(3)}) r=${pA.radius.toFixed(3)}`);
    console.log(`[KERF DEBUG] RingB pith[${ringB_pithIdx}]: (${pB.x.toFixed(3)}, ${pB.y.toFixed(3)}, ${pB.z.toFixed(3)}) r=${pB.radius.toFixed(3)}`);
    console.log(`[KERF DEBUG] C1    pith[${c1_pithIdx}]: (${c1Pith.x.toFixed(3)}, ${c1Pith.y.toFixed(3)}, ${c1Pith.z.toFixed(3)}) r=${c1Pith.radius.toFixed(3)}`);
    // Log first shell node of each ring for comparison
    const c1Shell0 = this.nodes[c1_shellStart];
    const shellA0 = this.nodes[ringA_shell[0]];
    const shellB0 = this.nodes[ringB_shell[0]];
    console.log(`[KERF DEBUG] RingA shell[0][${ringA_shell[0]}]: (${shellA0.x.toFixed(3)}, ${shellA0.y.toFixed(3)}, ${shellA0.z.toFixed(3)}) r=${shellA0.radius}`);
    console.log(`[KERF DEBUG] RingB shell[0][${ringB_shell[0]}]: (${shellB0.x.toFixed(3)}, ${shellB0.y.toFixed(3)}, ${shellB0.z.toFixed(3)}) r=${shellB0.radius}`);
    console.log(`[KERF DEBUG] C1    shell[0][${c1_shellStart}]: (${c1Shell0.x.toFixed(3)}, ${c1Shell0.y.toFixed(3)}, ${c1Shell0.z.toFixed(3)}) r=${c1Shell0.radius}`);
    // Distance from C1 pith to C1 shell[0]
    const dxPS = c1Pith.x - c1Shell0.x, dyPS = c1Pith.y - c1Shell0.y, dzPS = c1Pith.z - c1Shell0.z;
    console.log(`[KERF DEBUG] Dist(C1 pith -> C1 shell[0]) = ${Math.sqrt(dxPS*dxPS + dyPS*dyPS + dzPS*dzPS).toFixed(4)}`);
    
    // C2 Indices
    const c2_pithIdx = this.nodes.length;
    const c2_shellStart = c2_pithIdx + 1;
    
    // Add C2 Pith & Shell
    pushInterpNode(pA, pB, 1, segIdx + 1, t);
    for (let j = 0; j < nodesPerRing; j++) {
      const nA = this.nodes[ringA_shell[j]];
      const nB = this.nodes[ringB_shell[j]];
      const d1 = (nA.x - planePoint[0])*planeNormal[0] + (nA.y - planePoint[1])*planeNormal[1] + (nA.z - planePoint[2])*planeNormal[2];
      const d2 = (nB.x - planePoint[0])*planeNormal[0] + (nB.y - planePoint[1])*planeNormal[1] + (nB.z - planePoint[2])*planeNormal[2];
      const denom = d1 - d2;
      const tj = Math.abs(denom) < 1e-6 ? 0.5 : d1 / denom;
      const tjClamped = Math.max(0, Math.min(1, tj));
      pushInterpNode(nA, nB, 1, segIdx + 1, tjClamped);
    }
    
    // Retrieve the original pith-to-pith spring rest length before filter
    let originalPithRestLength = 0.5; // default fallback if not found
    for (const s of this.springs) {
      if ((s.idxA === ringA_pithIdx && s.idxB === ringB_pithIdx) ||
          (s.idxA === ringB_pithIdx && s.idxB === ringA_pithIdx)) {
        originalPithRestLength = s.restLength;
        break;
      }
    }

    const originalSegment = this.segments[segIdx];
    const leftSegment = originalSegment.slice(0, ringInSegIdx + 1);
    const rightSegment = originalSegment.slice(ringInSegIdx + 1);
    
    // Build sets of all existing node indices on the left and right of this specific cut
    const leftIndices = new Set<number>();
    for (const ring of leftSegment) {
      leftIndices.add(ring.pithIdx);
      ring.shellIndices.forEach(idx => leftIndices.add(idx));
    }
    
    const rightIndices = new Set<number>();
    for (const ring of rightSegment) {
      rightIndices.add(ring.pithIdx);
      ring.shellIndices.forEach(idx => rightIndices.add(idx));
    }
    
    // Internal rings for C1 and C2
    const c1_shell: number[] = [];
    for (let j = 0; j < nodesPerRing; j++) c1_shell.push(c1_shellStart + j);
    
    const c2_shell: number[] = [];
    for (let j = 0; j < nodesPerRing; j++) c2_shell.push(c2_shellStart + j);

    const vA = activeSegObj[ringInSegIdx].originalV;
    const vB = activeSegObj[ringInSegIdx + 1].originalV;
    const kerfV = vA + (vB - vA) * t;

    const c1Ring: RingTopology = { pithIdx: c1_pithIdx, shellIndices: c1_shell, originalV: kerfV };
    const c2Ring: RingTopology = { pithIdx: c2_pithIdx, shellIndices: c2_shell, originalV: kerfV };

    // Connect Kerf!
    const kerfTopology: KerfTopology = {
      leftRing: c1Ring,
      rightRing: c2Ring,
      springIndices: [],
      longitudinalSpringIndices: []
    };

    // Instead of deleting the A->B crossing springs, we convert them into kerf springs.
    // This perfectly preserves the un-cut stiffness of the log (Approach A), but ensures 
    // they are severed sequentially by the chainsaw blade alongside the visual C1->C2 kerf springs.
    for (let i = 0; i < this.springs.length; i++) {
      const s = this.springs[i];
      const crosses = (leftIndices.has(s.idxA) && rightIndices.has(s.idxB)) || 
                      (rightIndices.has(s.idxA) && leftIndices.has(s.idxB));
      if (crosses && !s.isKerf) {
        s.isKerf = true;
        kerfTopology.springIndices.push(i);
      }
    }

    const L_orig = originalPithRestLength;

    // Helper to calculate exact Euclidean distance between two nodes
    const getDistance = (idxA: number, idxB: number) => {
      const nA = this.nodes[idxA];
      const nB = this.nodes[idxB];
      const dx = nA.x - nB.x;
      const dy = nA.y - nB.y;
      const dz = nA.z - nB.z;
      return Math.sqrt(dx * dx + dy * dy + dz * dz);
    };

    const addRingSprings = (shell: number[], pithIdx: number) => {
      for (let j = 0; j < nodesPerRing; j++) {
        // Hoop
        const hoopRest = getDistance(shell[j], shell[(j + 1) % nodesPerRing]);
        this.addSpring(shell[j], shell[(j + 1) % nodesPerRing], false, hoopRest);
        // Radial
        const radialRest = getDistance(shell[j], pithIdx);
        this.addSpring(shell[j], pithIdx, false, radialRest);
        
        // Diametric cross bracing
        if (j < Math.floor(nodesPerRing / 2)) {
          const diamRest = getDistance(shell[j], shell[(j + Math.floor(nodesPerRing / 2)) % nodesPerRing]);
          this.addSpring(shell[j], shell[(j + Math.floor(nodesPerRing / 2)) % nodesPerRing], false, diamRest);
        }
        
        // Chordal bracing
        const chordRest = getDistance(shell[j], shell[(j + 2) % nodesPerRing]);
        this.addSpring(shell[j], shell[(j + 2) % nodesPerRing], false, chordRest);
      }
    };
    addRingSprings(c1_shell, c1_pithIdx);
    addRingSprings(c2_shell, c2_pithIdx);
    
    // Connect A -> C1 and C2 -> B with exact actual distances so they hold the cut plane perfectly
    const connectRings = (ring1_pith: number, ring1_shell: number[], ring2_pith: number, ring2_shell: number[]) => {
      const MAX_THRESHOLD = 3.0;
      // Pith-to-pith
      const pithRest = getDistance(ring1_pith, ring2_pith);
      const pithBreakThreshold = Math.min(MAX_THRESHOLD, 1.0 + (L_orig * (1.5 - 1.0)) / pithRest);
      this.addSpring(ring1_pith, ring2_pith, false, pithRest, 1.0, pithBreakThreshold);
      
      for (let j = 0; j < nodesPerRing; j++) {
        // Longitudinal
        const longRest = getDistance(ring1_shell[j], ring2_shell[j]);
        const longBreakThreshold = Math.min(MAX_THRESHOLD, 1.0 + (L_orig * (1.5 - 1.0)) / longRest);
        this.addSpring(ring1_shell[j], ring2_shell[j], false, longRest, 1.0, longBreakThreshold);
        
        // Diagonal shear (X-brace)
        const diagRest1 = getDistance(ring1_shell[j], ring2_shell[(j + 1) % nodesPerRing]);
        const diagBreakThreshold1 = Math.min(MAX_THRESHOLD, 1.0 + (L_orig * (1.5 - 1.0)) / diagRest1);
        this.addSpring(ring1_shell[j], ring2_shell[(j + 1) % nodesPerRing], false, diagRest1, 1.0, diagBreakThreshold1);

        const diagRest2 = getDistance(ring1_shell[j], ring2_shell[(j - 1 + nodesPerRing) % nodesPerRing]);
        const diagBreakThreshold2 = Math.min(MAX_THRESHOLD, 1.0 + (L_orig * (1.5 - 1.0)) / diagRest2);
        this.addSpring(ring1_shell[j], ring2_shell[(j - 1 + nodesPerRing) % nodesPerRing], false, diagRest2, 1.0, diagBreakThreshold2);
      }
    };
    
    // t gives the fraction along L_orig. Compute undeformed lengths of new segments.
    // Use Math.max(0.01, ...) to avoid 0-length springs if cut is exactly on the node
    const L_A_C1 = Math.max(0.01, t * L_orig - kerfWidth / 2);
    const L_C2_B = Math.max(0.01, (1.0 - t) * L_orig - kerfWidth / 2);
    connectRings(ringA_pithIdx, ringA_shell, c1_pithIdx, c1_shell);
    connectRings(c2_pithIdx, c2_shell, ringB_pithIdx, ringB_shell);
    
    // Kerf Topology already initialized above

    const addKerfSprings = () => {
      const MAX_THRESHOLD = 3.0;
      // Pith-to-pith
      const pithRest = getDistance(c1_pithIdx, c2_pithIdx);
      const pithBreakThreshold = Math.min(MAX_THRESHOLD, 1.0 + (L_orig * (1.5 - 1.0)) / pithRest);
      this.addSpring(c1_pithIdx, c2_pithIdx, true, pithRest, 1.0, pithBreakThreshold);
      kerfTopology.springIndices.push(this.springs.length - 1);
      
      for (let j = 0; j < nodesPerRing; j++) {
        // Longitudinal
        const longRest = getDistance(c1_shell[j], c2_shell[j]);
        const longBreakThreshold = Math.min(MAX_THRESHOLD, 1.0 + (L_orig * (1.5 - 1.0)) / longRest);
        this.addSpring(c1_shell[j], c2_shell[j], true, longRest, 1.0, longBreakThreshold);
        kerfTopology.longitudinalSpringIndices!.push(kerfTopology.springIndices.length);
        kerfTopology.springIndices.push(this.springs.length - 1);

        // Diagonal shear (X-brace)
        const nextRingNextIdx = c2_shell[(j + 1) % nodesPerRing];
        const diagRest1 = getDistance(c1_shell[j], nextRingNextIdx);
        const diagBreakThreshold1 = Math.min(MAX_THRESHOLD, 1.0 + (L_orig * (1.5 - 1.0)) / diagRest1);
        this.addSpring(c1_shell[j], nextRingNextIdx, true, diagRest1, 1.0, diagBreakThreshold1);
        kerfTopology.springIndices.push(this.springs.length - 1);
        
        const nextRingPrevIdx = c2_shell[(j - 1 + nodesPerRing) % nodesPerRing];
        const diagRest2 = getDistance(c1_shell[j], nextRingPrevIdx);
        const diagBreakThreshold2 = Math.min(MAX_THRESHOLD, 1.0 + (L_orig * (1.5 - 1.0)) / diagRest2);
        this.addSpring(c1_shell[j], nextRingPrevIdx, true, diagRest2, 1.0, diagBreakThreshold2);
        kerfTopology.springIndices.push(this.springs.length - 1);
        
      }
    };
    
    addKerfSprings();
    this.activeKerfs.push(kerfTopology);
    
    // Finalize Topology Update
    leftSegment.push(c1Ring);
    
    rightSegment.unshift(c2Ring);
    
    this.segments.splice(segIdx, 1, leftSegment, rightSegment);
    
    // Update segmentIdx for all nodes in the newly shifted right-side segments
    for (let s = segIdx + 1; s < this.segments.length; s++) {
      const seg = this.segments[s];
      for (const ring of seg) {
        this.nodes[ring.pithIdx].segmentIdx = s;
        for (const shellIdx of ring.shellIndices) {
          this.nodes[shellIdx].segmentIdx = s;
        }
      }
    }
  }
}
