import { LogModel } from './LogModel';
import { TerrainDef } from '../types';

// Physics engine tunable parameters & constants
export let GRAVITY = -9.8;

export function setGravity(value: number) {
  GRAVITY = value;
}
const NUM_ITERATIONS = 100;
const TIME_STEP = 1 / 60;
const SPRING_BREAK_THRESHOLD = 1.5; // 150% stretch (prevents shattering on floor impact)
const SPRING_STIFFNESS = 1.0;
const CAPSULE_COLLISION_DAMPING = 0.8;
const GROUND_DAMPING = 0.8;
const GROUND_FRICTION_DAMPING = 0.5; // Horizontal friction damping for ground contact
const GROUND_STATIC_VELOCITY_THRESHOLD = 0.1; // m/s - speed below which static friction locks horizontal motion
const ROTATIONAL_DAMPING_STUCK = 0.90;
const ROTATIONAL_DAMPING_NORMAL = 0.99; // Changed from 0.995 to damp jitter faster
const ROTATIONAL_STUCK_SPEED_SQ = 0.01;
const LINEAR_DAMPING_STUCK = 0.5; // Aggressive linear damping for static friction
const EXTERNAL_FORCE_RADIUS = 0.5;
const ENDCAP_COLLISION_DAMPING = 0.5;
const ENDCAP_SHEAR_FRICTION_STIFFNESS = 0.5; // In-loop lateral shear friction during contact
const ENDCAP_RESTITUTION_DAMPING = 0.2; // Dampens endcap normal velocity to prevent elastic popcorn bounce
const ENDCAP_TANGENTIAL_FRICTION_DAMPING = 0.3;
const MAX_ENDCAP_CORRECTION_PER_ITERATION = 0.005; // Max 5mm position correction per sub-step iteration

// New constants for bounded endcap collisions
const ENDCAP_COLLISION_RADIUS_PADDING = 0.02; // buffer for radial overlap checks

const MAX_ENDCAP_ANGLE_DEG = 80;
const MAX_ENDCAP_DOT_THRESHOLD = -Math.cos((MAX_ENDCAP_ANGLE_DEG * Math.PI) / 180); // ~-0.173648

export class Solver {
  private log: LogModel;
  private terrain: TerrainDef | undefined;
  
  private guidebarActive = false;
  private guidebarPosition = [0, 0, 0];
  private guidebarScale = [0, 0, 0];
  private guidebarQuat = [0, 0, 0, 1];
  private bindingPressure = 0;

  private endcapContactNormals: Map<number, { x: number; y: number; z: number }> = new Map();

  constructor(log: LogModel) {
    this.log = log;
  }

  public setTerrain(terrain: TerrainDef | undefined) {
    this.terrain = terrain;
  }

  public setGuidebar(active: boolean, pos?: [number, number, number], quat?: [number, number, number, number], scale?: [number, number, number]) {
    this.guidebarActive = active;
    if (active && pos && quat && scale) {
      this.guidebarPosition = pos;
      this.guidebarQuat = quat;
      this.guidebarScale = scale;
    }
  }

  public getBindingPressure(): number {
    return this.bindingPressure;
  }

  private getTerrainHeight(x: number, z: number): number {
    if (!this.terrain) return 0;

    const halfSize = this.terrain.size / 2;
    const step = this.terrain.size / this.terrain.segments;

    let u = (x + halfSize) / step;
    let v = (z + halfSize) / step;

    if (u < 0) u = 0;
    if (v < 0) v = 0;
    if (u >= this.terrain.segments) u = this.terrain.segments - 0.001;
    if (v >= this.terrain.segments) v = this.terrain.segments - 0.001;

    const u0 = Math.floor(u);
    const v0 = Math.floor(v);
    const u1 = u0 + 1;
    const v1 = v0 + 1;

    const du = u - u0;
    const dv = v - v0;

    const rowSize = this.terrain.segments + 1;
    const h00 = this.terrain.heightmap[v0 * rowSize + u0];
    const h10 = this.terrain.heightmap[v0 * rowSize + u1];
    const h01 = this.terrain.heightmap[v1 * rowSize + u0];
    const h11 = this.terrain.heightmap[v1 * rowSize + u1];

    const h0 = h00 * (1 - du) + h10 * du;
    const h1 = h01 * (1 - du) + h11 * du;

    return h0 * (1 - dv) + h1 * dv;
  }

  public tick(showTension: boolean = false) {
    const dt = TIME_STEP;
    this.bindingPressure = 0;
    this.endcapContactNormals.clear();

    // 1. Apply Forces & Predict Positions (Verlet Step)
    for (const node of this.log.nodes) {
      if (node.invMass === 0) continue;

      // Add gravity
      node.accY += GRAVITY;

      const velX = (node.x - node.oldX) / dt;
      const velY = (node.y - node.oldY) / dt;
      const velZ = (node.z - node.oldZ) / dt;

      // Apply damping friction
      const damping = 0.99;

      node.oldX = node.x;
      node.oldY = node.y;
      node.oldZ = node.z;

      node.x += velX * dt * damping + node.accX * dt * dt;
      node.y += velY * dt * damping + node.accY * dt * dt;
      node.z += velZ * dt * damping + node.accZ * dt * dt;
    }

    // 2. Interleaved Constraint Iteration Loop
    for (let i = 0; i < NUM_ITERATIONS; i++) {
      // Sub-Step A: Springs
      for (const spring of this.log.springs) {
        if (spring.broken) continue;

        const nA = this.log.nodes[spring.idxA];
        const nB = this.log.nodes[spring.idxB];

        const dx = nB.x - nA.x;
        const dy = nB.y - nA.y;
        const dz = nB.z - nA.z;
        const currentLength = Math.sqrt(dx * dx + dy * dy + dz * dz);

        if (currentLength === 0) continue;

        // Breakage check
        const threshold = spring.breakThreshold ?? SPRING_BREAK_THRESHOLD;
        if (currentLength / spring.restLength > threshold) {
          spring.broken = true;
          continue;
        }

        const diff = (currentLength - spring.restLength) / currentLength;
        const wA = nA.invMass;
        const wB = nB.invMass;
        const wSum = wA + wB;

        if (wSum === 0) continue;

        // Stiffness parameter
        const stiffness = spring.stiffness ?? SPRING_STIFFNESS;

        const correctionX = dx * diff * stiffness / wSum;
        const correctionY = dy * diff * stiffness / wSum;
        const correctionZ = dz * diff * stiffness / wSum;

        if (wA > 0) {
          nA.x += correctionX * wA;
          nA.y += correctionY * wA;
          nA.z += correctionZ * wA;
        }
        if (wB > 0) {
          nB.x -= correctionX * wB;
          nB.y -= correctionY * wB;
          nB.z -= correctionZ * wB;
        }
      }

      // Sub-Step C1: Guidebar Constraints
      this.enforceGuidebarConstraints(dt);

      // Sub-Step C2: Endcap Planar Constraints
      this.enforceEndcapConstraints();

      // Sub-Step D: Inter-Log Pith Collision (Edge-Edge)
      const numSegments = this.log.segments.length;

      const parent = new Array(numSegments);
      for (let i = 0; i < numSegments; i++) parent[i] = i;

      const find = (i: number): number => {
        if (parent[i] === i) return i;
        return parent[i] = find(parent[i]);
      };

      const union = (i: number, j: number) => {
        const rootI = find(i);
        const rootJ = find(j);
        if (rootI !== rootJ) parent[rootI] = rootJ;
      };

      for (const spring of this.log.springs) {
        if (spring.broken) continue;
        const segA = this.log.nodes[spring.idxA].segmentIdx;
        const segB = this.log.nodes[spring.idxB].segmentIdx;
        if (segA !== segB && segA !== undefined && segB !== undefined) {
          union(segA, segB);
        }
      }

      for (let s1 = 0; s1 < numSegments; s1++) {
        const segA = this.log.segments[s1];
        if (segA.length < 2) continue;

        for (let s2 = s1 + 1; s2 < numSegments; s2++) {
          // Skip collision between segments that are physically tethered (uncut kerf)
          if (find(s1) === find(s2)) continue;

          // Skip capsule-capsule collision between adjacent segments if they are still aligned end-to-end
          if (this.isAdjacentEndToEnd(s1, s2)) continue;

          const segB = this.log.segments[s2];
          if (segB.length < 2) continue;

          for (let r1 = 0; r1 < segA.length - 1; r1++) {
            const p1 = this.log.nodes[segA[r1].pithIdx];
            const q1 = this.log.nodes[segA[r1 + 1].pithIdx];
            if (p1.radius === 0 || q1.radius === 0) continue;

            for (let r2 = 0; r2 < segB.length - 1; r2++) {
              const p2 = this.log.nodes[segB[r2].pithIdx];
              const q2 = this.log.nodes[segB[r2 + 1].pithIdx];
              if (p2.radius === 0 || q2.radius === 0) continue;

              const d1x = q1.x - p1.x;
              const d1y = q1.y - p1.y;
              const d1z = q1.z - p1.z;
              const len1 = Math.sqrt(d1x * d1x + d1y * d1y + d1z * d1z);

              const d2x = q2.x - p2.x;
              const d2y = q2.y - p2.y;
              const d2z = q2.z - p2.z;
              const len2 = Math.sqrt(d2x * d2x + d2y * d2y + d2z * d2z);

              if (len1 === 0 || len2 === 0) continue;

              const rx = p1.x - p2.x;
              const ry = p1.y - p2.y;
              const rz = p1.z - p2.z;

              const a = d1x * d1x + d1y * d1y + d1z * d1z;
              const e = d2x * d2x + d2y * d2y + d2z * d2z;
              const f = d2x * rx + d2y * ry + d2z * rz;
              const c = d1x * rx + d1y * ry + d1z * rz;
              const b = d1x * d2x + d1y * d2y + d1z * d2z;

              let s = 0, t = 0;
              const denom = a * e - b * b;

              if (denom !== 0) {
                s = Math.max(0, Math.min(1, (b * f - c * e) / denom));
              }

              t = e === 0 ? 0 : (b * s + f) / e;

              if (t < 0) {
                t = 0;
                s = a === 0 ? 0 : Math.max(0, Math.min(1, -c / a));
              } else if (t > 1) {
                t = 1;
                s = a === 0 ? 0 : Math.max(0, Math.min(1, (b - c) / a));
              }

              const c1x = p1.x + d1x * s;
              const c1y = p1.y + d1y * s;
              const c1z = p1.z + d1z * s;

              const c2x = p2.x + d2x * t;
              const c2y = p2.y + d2y * t;
              const c2z = p2.z + d2z * t;

              const distVecX = c1x - c2x;
              const distVecY = c1y - c2y;
              const distVecZ = c1z - c2z;

              const distSq = distVecX * distVecX + distVecY * distVecY + distVecZ * distVecZ;

              if (distSq === 0) continue;
              const dist = Math.sqrt(distSq);
              const normX = distVecX / dist;
              const normY = distVecY / dist;
              const normZ = distVecZ / dist;

              // Dynamically flatten the capsule endcaps to model a true flat cylinder
              const dot1 = (normX * d1x + normY * d1y + normZ * d1z) / len1;
              const dot2 = (normX * d2x + normY * d2y + normZ * d2z) / len2;

              let cap1 = 0;
              if (s === 0) cap1 = Math.max(0, dot1);
              else if (s === 1) cap1 = Math.max(0, -dot1);

              let cap2 = 0;
              if (t === 0) cap2 = Math.max(0, -dot2);
              else if (t === 1) cap2 = Math.max(0, dot2);

              // Chamfer the endcaps: if the collision is mostly axial (cap > 0.7),
              // we steeply reduce the effective radius to 0. This ignores minor corner 
              // clipping when logs are slightly angled, preventing artificial separation.
              const getChamferedRadius = (radius: number, cap: number) => {
                if (cap < 0.4) return radius; // Full radius on sides
                if (cap > 0.8) return 0;      // 0 radius on flat ends (within ~36 degrees)
                // Smooth blend between 0.4 and 0.8
                const factor = (0.8 - cap) / 0.4;
                return radius * factor;
              };

              const rEff1 = getChamferedRadius(p1.radius, cap1);
              const rEff2 = getChamferedRadius(p2.radius, cap2);
              const totalR = rEff1 + rEff2;

              if (dist < totalR) {
                const penetration = totalR - dist;

                const wp1 = p1.invMass * (1 - s) * (1 - s);
                const wq1 = q1.invMass * s * s;
                const wp2 = p2.invMass * (1 - t) * (1 - t);
                const wq2 = q2.invMass * t * t;

                const W = wp1 + wq1 + wp2 + wq2;
                if (W > 0) {
                  const correction = (penetration / W) * CAPSULE_COLLISION_DAMPING; // Dampened to prevent popping

                  if (p1.invMass > 0) {
                    p1.x += normX * correction * p1.invMass * (1 - s);
                    p1.y += normY * correction * p1.invMass * (1 - s);
                    p1.z += normZ * correction * p1.invMass * (1 - s);
                  }
                  if (q1.invMass > 0) {
                    q1.x += normX * correction * q1.invMass * s;
                    q1.y += normY * correction * q1.invMass * s;
                    q1.z += normZ * correction * q1.invMass * s;
                  }

                  if (p2.invMass > 0) {
                    p2.x -= normX * correction * p2.invMass * (1 - t);
                    p2.y -= normY * correction * p2.invMass * (1 - t);
                    p2.z -= normZ * correction * p2.invMass * (1 - t);
                  }
                  if (q2.invMass > 0) {
                    q2.x -= normX * correction * q2.invMass * t;
                    q2.y -= normY * correction * q2.invMass * t;
                    q2.z -= normZ * correction * q2.invMass * t;
                  }
                }
              }
            }
          }
        }
      }

      // Sub-Step B: Ground Collision
      for (const node of this.log.nodes) {
        if (node.invMass > 0) {
          const r = node.radius || 0;
          const groundY = this.getTerrainHeight(node.x, node.z);
          if (node.y < groundY + r) {
            const penetration = (groundY + r) - node.y;
            node.y += penetration; // Support vertical weight without horizontal slope drift
          }
        }
      }
    }

    // 3. Finalize Velocity and Restitution
    // Handled inherently by Verlet when setting oldX/Y/Z, but for popcorn prevention & ground friction:
    for (const node of this.log.nodes) {
      if (node.invMass === 0) continue;

      const groundY = this.getTerrainHeight(node.x, node.z);
      const r = node.radius || 0;

      // Apply ground friction to all nodes in contact with terrain (shell and pith)
      if (node.y <= groundY + r + 0.05) {
        const vx = (node.x - node.oldX) / dt;
        const vz = (node.z - node.oldZ) / dt;
        const vy = (node.y - node.oldY) / dt;

        const horizontalSpeed = Math.sqrt(vx * vx + vz * vz);
        if (horizontalSpeed < GROUND_STATIC_VELOCITY_THRESHOLD) {
          // Static friction lock: completely zero horizontal velocity to prevent creep
          node.oldX = node.x;
          node.oldZ = node.z;
        } else {
          // Dynamic ground friction damping
          node.oldX = node.x - vx * dt * GROUND_FRICTION_DAMPING;
          node.oldZ = node.z - vz * dt * GROUND_FRICTION_DAMPING;
        }

        node.oldY = node.y - vy * dt * GROUND_DAMPING;
      }
    }

    // 3.1 Endcap Restitution Damping (Popcorn / Bounce Prevention for Endcaps)
    for (const [nodeIdx, norm] of this.endcapContactNormals) {
      const node = this.log.nodes[nodeIdx];
      if (!node || node.invMass === 0) continue;

      const vx = (node.x - node.oldX) / dt;
      const vy = (node.y - node.oldY) / dt;
      const vz = (node.z - node.oldZ) / dt;

      const vDotN = vx * norm.x + vy * norm.y + vz * norm.z;
      const targetVDotN = vDotN * ENDCAP_RESTITUTION_DAMPING;
      const deltaV = targetVDotN - vDotN;

      // Tangential velocity component
      const vTx = vx - vDotN * norm.x;
      const vTy = vy - vDotN * norm.y;
      const vTz = vz - vDotN * norm.z;

      // Apply restitution and tangential friction
      const vxNew = vx + deltaV * norm.x - vTx * ENDCAP_TANGENTIAL_FRICTION_DAMPING;
      const vyNew = vy + deltaV * norm.y - vTy * ENDCAP_TANGENTIAL_FRICTION_DAMPING;
      const vzNew = vz + deltaV * norm.z - vTz * ENDCAP_TANGENTIAL_FRICTION_DAMPING;

      node.oldX = node.x - vxNew * dt;
      node.oldY = node.y - vyNew * dt;
      node.oldZ = node.z - vzNew * dt;
    }

    // 3.5 Angular Damping / Rolling Resistance
    // Dampen the velocity of shell nodes relative to their pith node to prevent endless spinning
    for (const segment of this.log.segments) {
      for (const ring of segment) {
        const pith = this.log.nodes[ring.pithIdx];
        if (pith.invMass === 0) continue;

        // Calculate velocity vectors per frame (not per second, for simpler math)
        let pithVx = pith.x - pith.oldX;
        let pithVy = pith.y - pith.oldY;
        let pithVz = pith.z - pith.oldZ;

        // True linear speed squared in m/s
        const linearSpeedSq = (pithVx * pithVx + pithVy * pithVy + pithVz * pithVz) / (dt * dt);

        // If the log is moving very slowly (< 0.1 m/s), aggressively dampen rotation
        const isStuck = linearSpeedSq < ROTATIONAL_STUCK_SPEED_SQ;
        const rotationalDamping = isStuck ? ROTATIONAL_DAMPING_STUCK : ROTATIONAL_DAMPING_NORMAL;

        let linearDamping = 1.0;
        if (isStuck) {
           linearDamping = LINEAR_DAMPING_STUCK;
           pithVx *= linearDamping;
           pithVy *= linearDamping;
           pithVz *= linearDamping;
           
           pith.oldX = pith.x - pithVx;
           pith.oldY = pith.y - pithVy;
           pith.oldZ = pith.z - pithVz;
        }

        const pithSpeed = Math.sqrt(pithVx * pithVx + pithVy * pithVy + pithVz * pithVz);

        for (const shellIdx of ring.shellIndices) {
          const shellNode = this.log.nodes[shellIdx];

          let shellVx = shellNode.x - shellNode.oldX;
          let shellVy = shellNode.y - shellNode.oldY;
          let shellVz = shellNode.z - shellNode.oldZ;

          if (isStuck) {
             shellVx *= linearDamping;
             shellVy *= linearDamping;
             shellVz *= linearDamping;
          }

          // Relative velocity of shell node to pith node (this represents rotation and radial vibration)
          let relVx = shellVx - pithVx;
          let relVy = shellVy - pithVy;
          let relVz = shellVz - pithVz;

          const relSpeed = Math.sqrt(relVx * relVx + relVy * relVy + relVz * relVz);

          // Kinematic spin cap: the shell relative speed should not exceed the pith linear speed
          // We still apply a baseline rotational damping to simulate rolling resistance
          let finalRelSpeed = relSpeed * rotationalDamping;
          if (finalRelSpeed > pithSpeed) {
            finalRelSpeed = pithSpeed;
          }

          if (relSpeed > 0) {
            const scale = finalRelSpeed / relSpeed;
            relVx *= scale;
            relVy *= scale;
            relVz *= scale;
          }

          // Reconstruct old position with the clamped relative velocity
          shellNode.oldX = shellNode.x - (pithVx + relVx);
          shellNode.oldY = shellNode.y - (pithVy + relVy);
          shellNode.oldZ = shellNode.z - (pithVz + relVz);
        }
      }
    }

    // 4. Housekeeping
    for (const node of this.log.nodes) {
      node.accX = 0;
      node.accY = 0;
      node.accZ = 0;
      node.strain = 0;
    }

    // 5. Compute Strain for Visualization (Longitudinal Vector Projection)
    if (showTension) {
      const numNodes = this.log.nodes.length;
      const nodeAxisX = new Float32Array(numNodes);
      const nodeAxisY = new Float32Array(numNodes);
      const nodeAxisZ = new Float32Array(numNodes);

      for (const segment of this.log.segments) {
        const ringCount = segment.length;
        if (ringCount === 0) continue;

        for (let r = 0; r < ringCount; r++) {
          const rPrev = Math.max(0, r - 1);
          const rNext = Math.min(ringCount - 1, r + 1);

          const nPrev = this.log.nodes[segment[rPrev].pithIdx];
          const nNext = this.log.nodes[segment[rNext].pithIdx];

          let ax = nNext.x - nPrev.x;
          let ay = nNext.y - nPrev.y;
          let az = nNext.z - nPrev.z;
          let len = Math.sqrt(ax * ax + ay * ay + az * az);

          if (len > 1e-6) {
            ax /= len;
            ay /= len;
            az /= len;
          } else {
            ax = 1;
            ay = 0;
            az = 0;
          }

          const ring = segment[r];
          nodeAxisX[ring.pithIdx] = ax;
          nodeAxisY[ring.pithIdx] = ay;
          nodeAxisZ[ring.pithIdx] = az;

          for (const sIdx of ring.shellIndices) {
            nodeAxisX[sIdx] = ax;
            nodeAxisY[sIdx] = ay;
            nodeAxisZ[sIdx] = az;
          }
        }
      }

      for (const spring of this.log.springs) {
        if (spring.broken) continue;

        const nA = this.log.nodes[spring.idxA];
        const nB = this.log.nodes[spring.idxB];

        const dx = nB.x - nA.x;
        const dy = nB.y - nA.y;
        const dz = nB.z - nA.z;
        const currentLength = Math.sqrt(dx * dx + dy * dy + dz * dz);

        if (currentLength === 0) continue;

        const ex = dx / currentLength;
        const ey = dy / currentLength;
        const ez = dz / currentLength;

        let ax = nodeAxisX[spring.idxA] + nodeAxisX[spring.idxB];
        let ay = nodeAxisY[spring.idxA] + nodeAxisY[spring.idxB];
        let az = nodeAxisZ[spring.idxA] + nodeAxisZ[spring.idxB];
        let aLen = Math.sqrt(ax * ax + ay * ay + az * az);
        if (aLen > 1e-6) {
          ax /= aLen;
          ay /= aLen;
          az /= aLen;
        } else {
          ax = 1;
          ay = 0;
          az = 0;
        }

        const axialWeight = Math.abs(ex * ax + ey * ay + ez * az);

        // Positive = Tension, Negative = Compression
        const stiffness = spring.stiffness ?? SPRING_STIFFNESS;
        const force = (currentLength - spring.restLength) * stiffness * axialWeight;

        nA.strain += force;
        nB.strain += force;
      }

      // Propagate longitudinal strain across active kerfs for intact vs severed slices
      for (const kerf of this.log.activeKerfs) {
        const c1Ring = kerf.leftRing;
        const c2Ring = kerf.rightRing;

        const leftSeg = this.log.segments.find(s => s.length > 0 && s[s.length - 1].pithIdx === c1Ring.pithIdx);
        const rightSeg = this.log.segments.find(s => s.length > 0 && s[0].pithIdx === c2Ring.pithIdx);

        if (!leftSeg || leftSeg.length < 2 || !rightSeg || rightSeg.length < 2) continue;

        const ringA = leftSeg[leftSeg.length - 2];
        const ringB = rightSeg[1];

        const numNodes = c1Ring.shellIndices.length;
        const longIndices = kerf.longitudinalSpringIndices;

        if (longIndices && longIndices.length === numNodes) {
          for (let j = 0; j < numNodes; j++) {
            const springGlobalIdx = kerf.springIndices[longIndices[j]];
            const isBroken = this.log.springs[springGlobalIdx]?.broken ?? false;

            const c1Idx = c1Ring.shellIndices[j];
            const c2Idx = c2Ring.shellIndices[j];
            const aIdx = ringA.shellIndices[j];
            const bIdx = ringB.shellIndices[j];

            if (!isBroken && aIdx !== undefined && bIdx !== undefined) {
              // Intact wood fiber -> inherit continuous longitudinal strain from parent rings
              this.log.nodes[c1Idx].strain = this.log.nodes[aIdx].strain;
              this.log.nodes[c2Idx].strain = this.log.nodes[bIdx].strain;
            } else {
              // Severed wood fiber -> stress relieved by cut
              this.log.nodes[c1Idx].strain = 0;
              this.log.nodes[c2Idx].strain = 0;
            }
          }
        }

        // Pith node strain propagation
        const pithSpringGlobalIdx = kerf.springIndices[0];
        const isPithBroken = this.log.springs[pithSpringGlobalIdx]?.broken ?? false;
        if (!isPithBroken && ringA.pithIdx !== undefined && ringB.pithIdx !== undefined) {
          this.log.nodes[c1Ring.pithIdx].strain = this.log.nodes[ringA.pithIdx].strain;
          this.log.nodes[c2Ring.pithIdx].strain = this.log.nodes[ringB.pithIdx].strain;
        } else {
          this.log.nodes[c1Ring.pithIdx].strain = 0;
          this.log.nodes[c2Ring.pithIdx].strain = 0;
        }
      }
    }
  }

  public applyExternalForce(point: [number, number, number], dir: [number, number, number], magnitude: number) {
    const radius = EXTERNAL_FORCE_RADIUS; // Apply force to nodes within 0.5m radius of contact point
    const radiusSq = radius * radius;

    for (const n of this.log.nodes) {
      if (n.invMass === 0) continue;

      const dx = n.x - point[0];
      const dy = n.y - point[1];
      const dz = n.z - point[2];
      const distSq = dx * dx + dy * dy + dz * dz;

      if (distSq < radiusSq) {
        // Apply force weighted by distance (center is strongest)
        const weight = 1.0 - (Math.sqrt(distSq) / radius);
        const force = magnitude * weight;

        // F = ma -> a = F/m -> a = F * invMass
        n.accX += dir[0] * force * n.invMass;
        n.accY += dir[1] * force * n.invMass;
        n.accZ += dir[2] * force * n.invMass;
      }
    }
  }

  private enforceGuidebarConstraints(dt: number) {
    if (!this.guidebarActive) return;

    const pX = this.guidebarPosition[0];
    const pY = this.guidebarPosition[1];
    const pZ = this.guidebarPosition[2];

    const ux = -this.guidebarQuat[0];
    const uy = -this.guidebarQuat[1];
    const uz = -this.guidebarQuat[2];
    const w = this.guidebarQuat[3];

    const sX = this.guidebarScale[0] / 2;
    const sY = this.guidebarScale[1] / 2;
    const sZ = this.guidebarScale[2] / 2;

    const toLocal = (n: {x: number, y: number, z: number}) => {
      const vx = n.x - pX;
      const vy = n.y - pY;
      const vz = n.z - pZ;
      const tx = 2 * (uy * vz - uz * vy);
      const ty = 2 * (uz * vx - ux * vz);
      const tz = 2 * (ux * vy - uy * vx);
      return {
        x: vx + w * tx + (uy * tz - uz * ty),
        y: vy + w * ty + (uz * tx - ux * tz),
        z: vz + w * tz + (ux * ty - uy * tx)
      };
    };

    let leftFaceForce = 0;
    let rightFaceForce = 0;
    let contactNodesCount = 0;

    for (const kerf of this.log.activeKerfs) {
      const checkSide = (ringIndices: number[], isLeftSide: boolean) => {
        for (const idx of ringIndices) {
          const n = this.log.nodes[idx];
          if (n.invMass === 0) continue;

          const l = toLocal(n);
          // Check if node is inside the OBB
          if (Math.abs(l.x) < sX && Math.abs(l.y) < sY && Math.abs(l.z) < sZ) {
            contactNodesCount++;
            
            // Push it out to the nearest X face (assuming X is the broad face of the guidebar/kerf width)
            // The broad face is typically X if scale[0] is the width (which it is, kerf width is small)
            let projX = sX;
            if (l.x < 0) projX = -sX;
            
            const dx = projX - l.x;
            
            // Calculate force = m * dx / dt^2
            // Actually this loop happens NUM_ITERATIONS times per frame.
            // We just sum displacements for one iteration to get an instantaneous pressure reading, or sum total displacement over all iterations.
            // Let's sum absolute dx / dt^2 * mass
            const force = (Math.abs(dx) / n.invMass) / (dt * dt);
            if (isLeftSide) {
              leftFaceForce += force;
            } else {
              rightFaceForce += force;
            }

            // Apply world space correction
            // Convert local vector (dx, 0, 0) back to world
            // Inverse of inverse quaternion is just the original quaternion
            const ow = w;
            const ox = -ux;
            const oy = -uy;
            const oz = -uz;
            
            const tx = 2 * (oy * 0 - oz * 0);
            const ty = 2 * (oz * dx - ox * 0);
            const tz = 2 * (ox * 0 - oy * dx);
            
            const worldDx = dx + ow * tx + (oy * tz - oz * ty);
            const worldDy = 0 + ow * ty + (oz * tx - ox * tz);
            const worldDz = 0 + ow * tz + (ox * ty - oy * tx);

            n.x += worldDx * ENDCAP_COLLISION_DAMPING;
            n.y += worldDy * ENDCAP_COLLISION_DAMPING;
            n.z += worldDz * ENDCAP_COLLISION_DAMPING;
          }
        }
      };

      checkSide([kerf.leftRing.pithIdx, ...kerf.leftRing.shellIndices], true);
      checkSide([kerf.rightRing.pithIdx, ...kerf.rightRing.shellIndices], false);
    }

    if (contactNodesCount > 0) {
      // Calculate squeezing pressure
      // Area is roughly face area: 2 * sY * 2 * sZ
      const area = (2 * sY) * (2 * sZ) || 0.001; // Avoid div 0
      const squeezingForce = Math.min(leftFaceForce, rightFaceForce);
      // Average it out over the iterations, this is called NUM_ITERATIONS times per tick
      const pressure = (squeezingForce / area) / NUM_ITERATIONS;
      
      this.bindingPressure += pressure;
    }
  }

  private enforceEndcapConstraints() {
    for (const kerf of this.log.activeKerfs) {
      // Check if all springs in this kerf are broken (fully cut)
      if (!kerf.isFullyCut) {
        let allBroken = true;
        for (const idx of kerf.springIndices) {
          if (!this.log.springs[idx].broken) {
            allBroken = false;
            break;
          }
        }
        if (allBroken) {
          kerf.isFullyCut = true;
        }
      }

      const c1Ring = kerf.leftRing;
      const c2Ring = kerf.rightRing;

      const c1Pith = this.log.nodes[c1Ring.pithIdx];
      const c2Pith = this.log.nodes[c2Ring.pithIdx];

      const numNodes = c1Ring.shellIndices.length;
      if (numNodes === 0 || c2Ring.shellIndices.length === 0) continue;

      let c1NormX = 0, c1NormY = 0, c1NormZ = 0;
      for (let j = 0; j < numNodes; j++) {
        const p1 = this.log.nodes[c1Ring.shellIndices[j]];
        const p2 = this.log.nodes[c1Ring.shellIndices[(j + 1) % numNodes]];
        const v1x = p1.x - c1Pith.x, v1y = p1.y - c1Pith.y, v1z = p1.z - c1Pith.z;
        const v2x = p2.x - c1Pith.x, v2y = p2.y - c1Pith.y, v2z = p2.z - c1Pith.z;
        c1NormX += v1y * v2z - v1z * v2y;
        c1NormY += v1z * v2x - v1x * v2z;
        c1NormZ += v1x * v2y - v1y * v2x;
      }
      const c1Len = Math.sqrt(c1NormX * c1NormX + c1NormY * c1NormY + c1NormZ * c1NormZ);
      if (c1Len > 0) { c1NormX /= c1Len; c1NormY /= c1Len; c1NormZ /= c1Len; }

      let c2NormX = 0, c2NormY = 0, c2NormZ = 0;
      for (let j = 0; j < numNodes; j++) {
        const p1 = this.log.nodes[c2Ring.shellIndices[j]];
        const p2 = this.log.nodes[c2Ring.shellIndices[(j + 1) % numNodes]];
        const v1x = p1.x - c2Pith.x, v1y = p1.y - c2Pith.y, v1z = p1.z - c2Pith.z;
        const v2x = p2.x - c2Pith.x, v2y = p2.y - c2Pith.y, v2z = p2.z - c2Pith.z;
        c2NormX += v1y * v2z - v1z * v2y;
        c2NormY += v1z * v2x - v1x * v2z;
        c2NormZ += v1x * v2y - v1y * v2x;
      }
      const c2Len = Math.sqrt(c2NormX * c2NormX + c2NormY * c2NormY + c2NormZ * c2NormZ);
      if (c2Len > 0) { c2NormX /= c2Len; c2NormY /= c2Len; c2NormZ /= c2Len; }

      const toC2x = c2Pith.x - c1Pith.x;
      const toC2y = c2Pith.y - c1Pith.y;
      const toC2z = c2Pith.z - c1Pith.z;
      const toC2Len = Math.sqrt(toC2x * toC2x + toC2y * toC2y + toC2z * toC2z);

      if (c1NormX * toC2x + c1NormY * toC2y + c1NormZ * toC2z < 0) {
        c1NormX = -c1NormX; c1NormY = -c1NormY; c1NormZ = -c1NormZ;
      }
      if (c2NormX * toC2x + c2NormY * toC2y + c2NormZ * toC2z > 0) {
        c2NormX = -c2NormX; c2NormY = -c2NormY; c2NormZ = -c2NormZ;
      }

      let axisX = 1, axisY = 0, axisZ = 0;
      if (toC2Len > 1e-6) {
        axisX = toC2x / toC2Len;
        axisY = toC2y / toC2Len;
        axisZ = toC2z / toC2Len;
      }

      // Check if bending angle exceeds MAX_ENDCAP_ANGLE_DEG (80 degrees)
      const dot = c1NormX * c2NormX + c1NormY * c2NormY + c1NormZ * c2NormZ;
      if (dot > MAX_ENDCAP_DOT_THRESHOLD) {
        for (const idx of kerf.springIndices) {
          this.log.springs[idx].broken = true;
        }
        kerf.isFullyCut = true;
      }

      // Direct Pairwise Cut-Face Collision Resolution along Longitudinal Pith Axis
      // 1. Axial compression resolution along axis (axisX, axisY, axisZ):
      //    Eliminates all false transverse wedge forces caused by blade tilt or skewed face geometry.
      // 2. In-loop lateral shear friction:
      //    Restores lateral displacement d_perp to lock contacting rough wood faces from sliding past each other.
      for (let j = 0; j < numNodes; j++) {
        const idx1 = c1Ring.shellIndices[j];
        const idx2 = c2Ring.shellIndices[j];
        const n1 = this.log.nodes[idx1];
        const n2 = this.log.nodes[idx2];
        if (n1.invMass === 0 && n2.invMass === 0) continue;

        const dx = n2.x - n1.x;
        const dy = n2.y - n1.y;
        const dz = n2.z - n1.z;

        // Axial separation along longitudinal pith axis
        const dist = dx * axisX + dy * axisY + dz * axisZ;

        if (dist < 0) {
          // 1. Axial collision response (compression)
          const rawCorrection = -dist * ENDCAP_COLLISION_DAMPING;
          const correction = Math.min(rawCorrection, MAX_ENDCAP_CORRECTION_PER_ITERATION);
          const halfCorr = correction * 0.5;

          if (n2.invMass > 0) {
            n2.x += axisX * halfCorr;
            n2.y += axisY * halfCorr;
            n2.z += axisZ * halfCorr;
            this.endcapContactNormals.set(idx2, { x: axisX, y: axisY, z: axisZ });
          }

          if (n1.invMass > 0) {
            n1.x -= axisX * halfCorr;
            n1.y -= axisY * halfCorr;
            n1.z -= axisZ * halfCorr;
            this.endcapContactNormals.set(idx1, { x: -axisX, y: -axisY, z: -axisZ });
          }

          // 2. In-loop lateral shear friction (locks faces from sliding sideways while touching)
          const perpX = dx - dist * axisX;
          const perpY = dy - dist * axisY;
          const perpZ = dz - dist * axisZ;

          const shearCorrX = perpX * ENDCAP_SHEAR_FRICTION_STIFFNESS * 0.5;
          const shearCorrY = perpY * ENDCAP_SHEAR_FRICTION_STIFFNESS * 0.5;
          const shearCorrZ = perpZ * ENDCAP_SHEAR_FRICTION_STIFFNESS * 0.5;

          if (n2.invMass > 0) {
            n2.x -= shearCorrX;
            n2.y -= shearCorrY;
            n2.z -= shearCorrZ;
          }
          if (n1.invMass > 0) {
            n1.x += shearCorrX;
            n1.y += shearCorrY;
            n1.z += shearCorrZ;
          }
        }
      }

      // Resolve Pith-to-Pith penetration along longitudinal axis
      if (c1Pith.invMass > 0 || c2Pith.invMass > 0) {
        const pDx = c2Pith.x - c1Pith.x;
        const pDy = c2Pith.y - c1Pith.y;
        const pDz = c2Pith.z - c1Pith.z;
        const pDist = pDx * axisX + pDy * axisY + pDz * axisZ;

        if (pDist < 0) {
          const rawCorrection = -pDist * ENDCAP_COLLISION_DAMPING;
          const correction = Math.min(rawCorrection, MAX_ENDCAP_CORRECTION_PER_ITERATION);
          const halfCorr = correction * 0.5;

          if (c2Pith.invMass > 0) {
            c2Pith.x += axisX * halfCorr;
            c2Pith.y += axisY * halfCorr;
            c2Pith.z += axisZ * halfCorr;
            this.endcapContactNormals.set(c2Ring.pithIdx, { x: axisX, y: axisY, z: axisZ });
          }

          if (c1Pith.invMass > 0) {
            c1Pith.x -= axisX * halfCorr;
            c1Pith.y -= axisY * halfCorr;
            c1Pith.z -= axisZ * halfCorr;
            this.endcapContactNormals.set(c1Ring.pithIdx, { x: -axisX, y: -axisY, z: -axisZ });
          }
        }
      }
    }
  }

  private isAdjacentEndToEnd(s1: number, s2: number): boolean {
    for (const kerf of this.log.activeKerfs) {
      const leftSeg = this.log.nodes[kerf.leftRing.pithIdx].segmentIdx;
      const rightSeg = this.log.nodes[kerf.rightRing.pithIdx].segmentIdx;

      if ((leftSeg === s1 && rightSeg === s2) || (leftSeg === s2 && rightSeg === s1)) {
        // Measure distance between adjacent cut piths
        const pLeft = this.log.nodes[kerf.leftRing.pithIdx];
        const pRight = this.log.nodes[kerf.rightRing.pithIdx];

        const dx = pLeft.x - pRight.x;
        const dy = pLeft.y - pRight.y;
        const dz = pLeft.z - pRight.z;
        const distSq = dx * dx + dy * dy + dz * dz;

        // Log diameter = 2 * radius (e.g. 0.4m)
        const diameter = (pLeft.radius || 0.2) * 2.0;

        if (distSq < diameter * diameter) {
          return true; // Still end-to-end
        }
      }
    }
    return false;
  }
}
